// MARK: - Défi Gloire du Passé
//
// 50 fictional legends inspired by archetypes rather than real players — no real name,
// club or likeness is used anywhere. Unlock costs follow the same price bands as the
// Boutique: the entry challenges are reachable in ~10–15 careers, the final ones take 100+.
//
// `targetScore` is compared against FDGameEngine.legendScore, which weighs goals, assists,
// silverware, individual awards and caps. For reference, a very strong career lands around
// 500–550, so the last tier is meant to require a genuinely exceptional run.

struct FDLegendChallenge: Identifiable, Hashable {
    let id: String
    let name: String
    let era: String
    let nationality: String
    let position: FDPosition
    let style: FDStyle
    let personality: FDPersonality
    let archetype: String
    let unlockCost: Int
    let targetScore: Int

    var tier: Int {
        switch unlockCost {
        case ..<60: return 1
        case ..<140: return 2
        case ..<260: return 3
        default: return 4
        }
    }
}

/// Alias used by the Défis screen's redesigned UI.
typealias FDChallenge = FDLegendChallenge

// MARK: - Fil conducteur d'une légende

/// Une étape du chemin qu'a suivi la légende poursuivie : le club qu'elle a rejoint à cet
/// âge-là, le transfert qui a tout changé, la finale qui l'a faite. Le joueur la reçoit à
/// l'âge correspondant et décide s'il refait le même choix ou s'il écrit autre chose.
struct FDLegendStep {
    /// L'âge auquel la légende a vécu ce moment — et auquel le joueur y sera confronté.
    let age: Int
    /// Le lieu du moment, affiché en tête de carte.
    let place: String
    /// Le récit de ce qu'a fait la légende, et de ce qui se présente au joueur.
    let text: String
    let followLabel: String
    let followHint: String
    let followEffects: [FDEffect]
    let ownLabel: String
    let ownHint: String
    let ownEffects: [FDEffect]
    /// Quand l'étape est un transfert, la destination que suivre la légende implique :
    /// "sommet", "grand", "modeste", "etranger", "rival", "retour" ou "inferieur".
    /// Le moteur la traduit en club réel au moment où la scène se présente.
    var followMove: String? = nil
    /// La destination de l'autre route, quand s'écarter veut dire partir ailleurs.
    var ownMove: String? = nil
}

/// Le chemin de chaque légende, identifiant par identifiant. Suivre la route donne ce
/// qu'elle avait — et coûte ce qu'elle a payé ; s'en écarter rend au joueur sa propre
/// carrière, avec ce que ça vaut et ce que ça retire.
func fdLegendPath(_ id: String?) -> [FDLegendStep] {
    guard let id = id else { return [] }
    return FDLegendPaths[id] ?? []
}

