            ownHint: "Tu es resté au pays, dans le grand club, à ton poste habituel. Tu es près des tiens, et le numéro dix est à un autre.",
            ownEffects: [FDEffect(rel: "famille", delta: 7), FDEffect(cond: "moral", delta: 5), FDEffect(attr: .vision, delta: -2)],
            followMove: "etranger",
            ownMove: "grand"),
        FDLegendStep(
            age: 23, place: "Bureau du coach",
            text: "À vingt-trois ans, un coach lui a demandé de jouer sur un côté, loin de l'axe où il aimait recevoir le ballon, pour équilibrer l'équipe. Il a dit oui pendant deux saisons entières avant de retrouver sa place. On te demande ce sacrifice ce matin, avec les mêmes deux saisons en perspective.",
            followLabel: "Jouer sur un côté, comme lui",
            followHint: "Tu as accepté le côté pendant deux ans. L'équipe a été équilibrée, et tu as passé deux saisons loin de tes ballons.",
            followEffects: [FDEffect(attr: .centres, delta: 5), FDEffect(attr: .endurance, delta: 4), FDEffect(rel: "coach", delta: 6), FDEffect(cond: "confiance", delta: -4)],
            ownLabel: "Refuser de quitter l'axe",
            ownHint: "Tu as refusé de quitter l'axe. Tu es resté toi-même, et le coach a déséquilibré son équipe autrement.",
            ownEffects: [FDEffect(attr: .vision, delta: 4), FDEffect(cond: "confiance", delta: 5), FDEffect(rel: "coach", delta: -5)]),
        FDLegendStep(
            age: 27, place: "Vestiaire, avant une finale internationale",
            text: "Sa plus grande finale, Djorkaieff l'a jouée avec la consigne de ne pas prendre de risque, lui dont tout le jeu reposait sur le risque. Il a suivi la consigne quatre-vingts minutes puis il a tenté la passe qui a tout changé. Le coach vient de te donner exactement la même consigne pour ce soir.",
            followLabel: "Suivre la consigne, puis oser au bon moment",
            followHint: "Tu as respecté la consigne quatre-vingts minutes, puis tu as tenté la passe. Elle est passée, et c'est celle-là qu'on repasse encore.",
            followEffects: [FDEffect(attr: .vision, delta: 6), FDEffect(attr: .passe, delta: 5), FDEffect(cond: "reputation", delta: 9), FDEffect(cond: "fatigue", delta: 7)],
            ownLabel: "Jouer ton jeu dès la première minute",
            ownHint: "Tu as joué ton jeu tout de suite. Trois ballons magnifiques, deux pertes de balle dangereuses, et un coach furieux.",
            ownEffects: [FDEffect(attr: .passe, delta: 4), FDEffect(cond: "confiance", delta: 5), FDEffect(rel: "coach", delta: -6)]),
        FDLegendStep(
            age: 29, place: "Terrain, demi-finale internationale",
            text: "Sa passe la plus célèbre est une talonnade en demi-finale de Coupe du monde, à la 89e minute, sur une action où frapper était plus logique. Il a dit qu'il avait entendu le pas de son coéquipier. Tu as le but ouvert et un bruit de pas dans ton dos.",
            followLabel: "Tenter la talonnade",
            followHint: "Tu as tenté la talonnade à la 89e d'une demi-finale de Coupe du monde. Ton coéquipier l'a marqué, et c'est ta passe qu'on repasse.",
            followEffects: [FDEffect(attr: .vision, delta: 7), FDEffect(attr: .passe, delta: 5), FDEffect(cond: "reputation", delta: 11), FDEffect(rel: "vestiaire", delta: 7)],
            ownLabel: "Frapper toi-même",
            ownHint: "Tu as frappé toi-même. C'était le choix logique, et le gardien a détourné en corner.",
            ownEffects: [FDEffect(attr: .tir, delta: 5), FDEffect(cond: "reputation", delta: -3), FDEffect(cond: "confiance", delta: -3)]),
        FDLegendStep(
            age: 32, place: "Salon familial",
            text: "À trente-deux ans, il a choisi de finir dans le club de sa ville, en troisième division, pour que ses enfants le voient jouer en vrai avant qu'il s'arrête. Personne dans le milieu n'a compris. Le club de ta ville vient de t'appeler, et tes enfants n'ont jamais mis les pieds dans ton stade actuel.",
            followLabel: "Finir dans le club de ta ville",
