            ownHint: "Tu es resté au plus haut niveau jusqu'au bout. Tes enfants t'ont vu à la télévision, comme d'habitude.",
            ownEffects: [FDEffect(cond: "reputation", delta: 6), FDEffect(money: 90000), FDEffect(rel: "famille", delta: -5)],
            followMove: "retour"),
    ],
    "legend_muraille_rousse": [
        FDLegendStep(
            age: 19, place: "Salle vidéo",
            text: "Krool lisait le jeu deux temps avant tout le monde parce qu'il passait ses journées à regarder des matchs entiers sans jamais suivre le ballon — uniquement les mouvements sans ballon. Un analyste te propose ce travail-là, et c'est deux heures par jour à regarder ce que personne ne regarde.",
            followLabel: "Regarder le jeu sans le ballon, comme lui",
            followHint: "Tu as passé deux heures par jour à regarder ce que personne ne regarde. Aujourd'hui tu vois les choses trois secondes avant les autres.",
            followEffects: [FDEffect(attr: .vision, delta: 6), FDEffect(attr: .interception, delta: 5), FDEffect(cond: "fatigue", delta: 6), FDEffect(cond: "moral", delta: -3)],
