            followEffects: [FDEffect(attr: .control, delta: 5), FDEffect(attr: .vision, delta: 4), FDEffect(rel: "coach", delta: -7), FDEffect(cond: "reputation", delta: 6)],
            ownLabel: "Respecter la consigne",
            ownHint: "Tu as respecté la consigne à la lettre. La défense est stable, et personne ne t'a jamais vu faire ce que tu sais faire.",
            ownEffects: [FDEffect(attr: .placement, delta: 5), FDEffect(rel: "coach", delta: 6), FDEffect(cond: "confiance", delta: -3)]),
        FDLegendStep(
            age: 27, place: "Terrain, finale internationale",
            text: "Sa finale de Coupe du monde reste la plus commentée de sa carrière : il est monté marquer, puis il a perdu le ballon sur l'action qui a tout renversé. Il a toujours refusé de dire qu'il regrettait. Il reste dix minutes, vous menez d'un but, et le coup franc est pour toi si tu montes.",
            followLabel: "Monter quand même, comme lui",
            followHint: "Tu es monté sur le coup franc à dix minutes de la fin. Ce que tu as fait ce soir-là, on en parlera dans les deux sens pendant vingt ans.",
