    "legend_gunner": [
        FDLegendStep(
            age: 18, place: "Terrain d'entraînement",
            text: "Walcourt a signé à dix-huit ans dans un club qui lui a promis une chose précise : jamais plus de trente matchs par saison, pour protéger ses ischios. Il a tenu quinze ans avec ce contrat-là. Le club te propose ce même deal aujourd'hui, et il te ferme la porte des grandes saisons à quarante matchs.",
            followLabel: "Accepter le quota de matchs, comme lui",
            followHint: "Tu as accepté de ne jamais dépasser trente matchs. Tes ischios ont tenu quinze ans, et tu as raté la moitié des grandes soirées.",
            followEffects: [FDEffect(cond: "forme", delta: 7), FDEffect(cond: "fatigue", delta: -8), FDEffect(cond: "reputation", delta: -5)],
