    ],
    "legend_sorcier": [
        FDLegendStep(
            age: 18, place: "Terrain de son quartier",
            text: "Millar a refusé de partir en Europe à dix-huit ans pour rester deux ans de plus au pays, où il est devenu une idole avant même d'avoir joué un match européen. Tout le monde lui a dit qu'il gâchait sa carrière. Une offre européenne est arrivée cette semaine, et ton pays entier a un avis dessus.",
            followLabel: "Rester au pays deux ans de plus",
            followHint: "Tu es resté deux ans au pays. Tout un continent connaît ton nom, et l'Europe a attendu.",
            followEffects: [FDEffect(rel: "fans", delta: 9), FDEffect(cond: "moral", delta: 6), FDEffect(cond: "reputation", delta: 4), FDEffect(money: -60000)],
            ownLabel: "Partir en Europe tout de suite",
            ownHint: "Tu es parti tout de suite. Tu as gagné trois ans d'expérience européenne, et le pays a trouvé que tu l'avais quitté trop vite.",
            ownEffects: [FDEffect(cond: "reputation", delta: 7), FDEffect(money: 70000), FDEffect(rel: "fans", delta: -6)],
            ownMove: "etranger"),
        FDLegendStep(
            age: 22, place: "Zone mixte",
            text: "Millar dribblait en souriant, ce que les défenseurs prenaient comme une insulte. À vingt-deux ans, on lui a demandé publiquement d'arrêter de sourire quand il éliminait quelqu'un. Il a répondu qu'il ne savait pas faire autrement. Un journaliste vient de te poser la même question, mot pour mot.",
            followLabel: "Continuer à jouer avec le sourire",
            followHint: "Tu as continué à jouer et à sourire. Les tribunes t'adorent, et tu prends un coup par match depuis.",
            followEffects: [FDEffect(cond: "confiance", delta: 6), FDEffect(rel: "fans", delta: 8), FDEffect(cond: "forme", delta: -4), FDEffect(rel: "vestiaire", delta: -3)],
            ownLabel: "Promettre de rester sobre",
            ownHint: "Tu as promis de rester sobre. Les défenseurs t'ont laissé tranquille, et le public a trouvé que tu jouais moins bien.",
            ownEffects: [FDEffect(attr: .sangfroid, delta: 4), FDEffect(rel: "coach", delta: 4), FDEffect(rel: "fans", delta: -4)]),
        FDLegendStep(
            age: 24, place: "Aéroport",
            text: "À vingt-quatre ans, Millar a signé dans un championnat européen mineur plutôt que dans un grand club, parce que le club mineur acceptait qu'il rentre au pays trois fois par an. Il n'a jamais regretté. Le grand club exige une disponibilité totale, et le petit accepte tes conditions.",
            followLabel: "Choisir le club qui te laisse rentrer",
            followHint: "Tu as choisi le club qui te laisse rentrer au pays trois fois par an. Ta famille t'a vu grandir, et ta carrière a plafonné plus bas.",
            followEffects: [FDEffect(rel: "famille", delta: 8), FDEffect(cond: "moral", delta: 7), FDEffect(cond: "reputation", delta: -5), FDEffect(money: -60000)],
            ownLabel: "Choisir le grand club",
            ownHint: "Tu as choisi le grand club et sa disponibilité totale. Tu as joué au sommet, et tu es rentré chez toi deux fois en six ans.",
            ownEffects: [FDEffect(cond: "reputation", delta: 8), FDEffect(money: 130000), FDEffect(rel: "famille", delta: -7)],
            followMove: "modeste",
            ownMove: "grand"),
        FDLegendStep(
            age: 26, place: "Terrain, huitième de finale internationale",
            text: "Sa soirée de légende : deux buts et une danse de célébration devant le banc adverse, en Coupe du monde, à trente-huit ans dans son cas — mais le geste qui a fait sa légende, il l'avait déjà fait à vingt-six. Tu viens de marquer, la caméra te cherche, et le banc adverse est à dix mètres.",
            followLabel: "Célébrer devant eux, comme lui",
            followHint: "Tu as célébré devant leur banc. La séquence a fait le tour du monde, et l'arbitre a sorti le carton.",
            followEffects: [FDEffect(cond: "reputation", delta: 9), FDEffect(rel: "fans", delta: 7), FDEffect(rel: "coach", delta: -4), FDEffect(cond: "fatigue", delta: 5)],
            ownLabel: "Célébrer avec les tiens, sobrement",
            ownHint: "Tu as célébré avec tes coéquipiers, sans provocation. Personne n'a rien à redire, et personne ne s'en souviendra.",
            ownEffects: [FDEffect(rel: "vestiaire", delta: 5), FDEffect(cond: "moral", delta: 4), FDEffect(cond: "reputation", delta: -3)]),
        FDLegendStep(
            age: 29, place: "Terrain, phase de groupes internationale",
            text: "Le moment de bascule : à vingt-neuf ans, il a marqué deux buts en Coupe du monde et il est devenu, en une soirée, le premier joueur de son continent que le monde entier connaissait. Il avait demandé à jouer alors qu'il n'était pas titulaire. Le sélectionneur ne t'a pas prévu ce soir.",
            followLabel: "Aller réclamer ta place au sélectionneur",
            followHint: "Tu es allé réclamer ta place. Il t'a lancé, tu as marqué deux fois, et le monde entier a appris ton nom en une soirée.",
            followEffects: [FDEffect(cond: "reputation", delta: 12), FDEffect(cond: "confiance", delta: 7), FDEffect(rel: "coach", delta: -3), FDEffect(cond: "fatigue", delta: 7)],
            ownLabel: "Attendre qu'il te lance",
            ownHint: "Tu as attendu qu'il te lance. Il ne l'a pas fait, et le tournoi s'est terminé sans toi.",
            ownEffects: [FDEffect(rel: "coach", delta: 5), FDEffect(cond: "moral", delta: -5), FDEffect(cond: "reputation", delta: -6)]),
        FDLegendStep(
            age: 33, place: "Centre national",
            text: "À trente-trois ans, alors que tout le monde le disait fini, il a été rappelé en sélection pour un dernier tournoi et il y a été décisif. Il avait passé six mois à s'entraîner seul pour ça. Le sélectionneur hésite à te rappeler, et il te dit franchement dans quel état il te trouve.",
            followLabel: "T'entraîner seul six mois pour revenir",
            followHint: "Tu t'es entraîné seul pendant six mois pour arracher ce rappel. Tu l'as eu, et tu as été décisif.",
            followEffects: [FDEffect(attr: .determination, delta: 7), FDEffect(cond: "forme", delta: 6), FDEffect(cond: "reputation", delta: 8), FDEffect(cond: "fatigue", delta: 9)],
            ownLabel: "Accepter que c'est fini en sélection",
            ownHint: "Tu as accepté que la sélection était derrière toi. Tu as fini ta saison de club tranquillement, sans rien forcer.",
            ownEffects: [FDEffect(cond: "moral", delta: 5), FDEffect(cond: "forme", delta: 4), FDEffect(cond: "reputation", delta: -5)]),
    ],
    "legend_general": [
        FDLegendStep(
            age: 19, place: "Vestiaire, après une défaite",
            text: "Ruggieri gueulait sur tout le monde, et tout le monde jouait mieux. La première fois, il avait dix-neuf ans et il a passé un savon à un international de trente-deux ans devant tout le vestiaire. Il a failli être exclu du groupe. Vous venez de perdre bêtement, et le même genre de silence règne ici.",
            followLabel: "Passer le savon, comme lui",
            followHint: "Tu as passé le savon devant tout le monde, à dix-neuf ans. Deux anciens ont voulu ta peau, et l'équipe n'a plus jamais joué comme ça.",
            followEffects: [FDEffect(attr: .leadership, delta: 6), FDEffect(rel: "vestiaire", delta: -6), FDEffect(cond: "reputation", delta: 5), FDEffect(cond: "fatigue", delta: 5)],
            ownLabel: "Te taire, ce n'est pas ta place",
            ownHint: "Tu t'es tu, comme un jeune doit le faire. Le vestiaire t'a trouvé sage, et rien n'a changé du tout.",
