            followLabel: "Forcer ton départ, comme lui",
            followHint: "Tu as forcé ton départ en refusant de t'entraîner dix jours. Tu as obtenu ton transfert, et une réputation qui te suit encore.",
            followEffects: [FDEffect(cond: "reputation", delta: 5), FDEffect(money: 100000), FDEffect(rel: "president", delta: -9), FDEffect(rel: "vestiaire", delta: -5)],
            ownLabel: "Rester et faire avec",
            ownHint: "Tu es resté et tu as fait avec. Le club n'a rien recruté, et personne ne t'a rien reproché.",
            ownEffects: [FDEffect(rel: "president", delta: 6), FDEffect(rel: "vestiaire", delta: 5), FDEffect(cond: "moral", delta: -4)],
            followMove: "grand"),
        FDLegendStep(
            age: 23, place: "Terrain d'entraînement",
            text: "Ruggieri a construit son autorité sur un principe simple : ne jamais perdre un duel à l'entraînement, quel qu'en soit le prix. Trois coéquipiers se sont blessés contre lui en deux ans. Le staff vient de te demander de lever le pied dans les oppositions, parce que ça commence à faire beaucoup.",
            followLabel: "Ne rien lâcher, même à l'entraînement",
            followHint: "Tu n'as rien lâché, même le mardi matin. Le groupe te craint, et deux coéquipiers ont fini à l'infirmerie à cause de toi.",
            followEffects: [FDEffect(attr: .tacle, delta: 5), FDEffect(attr: .determination, delta: 5), FDEffect(rel: "vestiaire", delta: -6), FDEffect(rel: "staff", delta: -4)],
            ownLabel: "Lever le pied dans les oppositions",
            ownHint: "Tu as levé le pied à l'entraînement. Le vestiaire respire, et tu as perdu un peu de ce qui te rendait redoutable.",
            ownEffects: [FDEffect(rel: "vestiaire", delta: 6), FDEffect(rel: "staff", delta: 5), FDEffect(attr: .tacle, delta: -2)]),
        FDLegendStep(
            age: 27, place: "Rond central, finale internationale",
            text: "Sa finale de Coupe du monde, Ruggieri l'a commencée en allant dire deux mots à chaque adversaire pendant l'échauffement, un par un, sans hausser le ton. Trois d'entre eux ont joué à côté de leurs crampons. Tu as vingt minutes avant le coup d'envoi et le même vestiaire d'en face à portée de voix.",
            followLabel: "Aller les chercher un par un",
            followHint: "Tu es allé parler à chacun d'eux pendant l'échauffement. Deux ont perdu leurs moyens, et l'arbitre t'a averti avant même le coup d'envoi.",
            followEffects: [FDEffect(attr: .leadership, delta: 6), FDEffect(cond: "reputation", delta: 7), FDEffect(rel: "media", delta: -4), FDEffect(cond: "fatigue", delta: 6)],
            ownLabel: "Rester avec ton groupe",
            ownHint: "Tu es resté avec les tiens. Échauffement normal, match normal, et personne n'a été déstabilisé.",
            ownEffects: [FDEffect(rel: "vestiaire", delta: 5), FDEffect(attr: .sangfroid, delta: 4), FDEffect(cond: "reputation", delta: -3)]),
        FDLegendStep(
            age: 29, place: "Terrain, finale internationale",
            text: "Le carton qui a fait sa légende : à vingt-neuf ans, en finale de Coupe du monde, il a pris un rouge pour avoir défendu un coéquipier agressé, à la 85e minute. Son pays a perdu à dix. Il a dit qu'il le referait. Un adversaire vient de sécher ton coéquipier au sol, en finale.",
            followLabel: "Aller le défendre, quoi qu'il arrive",
            followHint: "Tu es allé défendre ton coéquipier, et tu as pris le rouge en finale. Ton pays a perdu à dix, et ton vestiaire ne l'oubliera jamais.",
            followEffects: [FDEffect(rel: "vestiaire", delta: 10), FDEffect(attr: .leadership, delta: 5), FDEffect(cond: "reputation", delta: 5), FDEffect(rel: "media", delta: -6)],
            ownLabel: "Retenir ton geste",
            ownHint: "Tu as retenu ton geste. La finale s'est jouée à onze contre onze, et ton coéquipier est resté au sol.",
            ownEffects: [FDEffect(attr: .sangfroid, delta: 6), FDEffect(rel: "media", delta: 5), FDEffect(rel: "vestiaire", delta: -5)]),
        FDLegendStep(
            age: 31, place: "Bureau du coach",
            text: "À trente et un ans, on lui a proposé de devenir entraîneur-joueur d'un club en perdition. Il a accepté et il a fait les deux pendant deux ans, en dormant quatre heures par nuit. Le club te fait exactement cette proposition ce matin, dans la même situation désespérée.",
            followLabel: "Être entraîneur et joueur, comme lui",
            followHint: "Tu as tenu les deux rôles pendant deux ans, à quatre heures de sommeil par nuit. Le club a survécu, et toi à moitié.",
            followEffects: [FDEffect(attr: .leadership, delta: 7), FDEffect(cond: "reputation", delta: 6), FDEffect(cond: "fatigue", delta: 14), FDEffect(cond: "forme", delta: -7)],
            ownLabel: "Rester joueur, uniquement",
            ownHint: "Tu es resté joueur. Tu as donné cent pour cent sur le terrain, et le club a coulé sans toi à la barre.",
            ownEffects: [FDEffect(cond: "forme", delta: 6), FDEffect(cond: "moral", delta: 4), FDEffect(rel: "president", delta: -4)]),
    ],
    "legend_pieuvre": [
        FDLegendStep(
            age: 18, place: "Vestiaire",
            text: "Casillo est devenu titulaire à dix-huit ans parce que le gardien numéro un s'est blessé un mercredi soir. Il n'a plus jamais rendu la place. Ton numéro un vient de se blesser hier, et le coach a dit qu'il verrait match après match — ce qui veut dire qu'il ne t'a pas encore choisi.",
            followLabel: "Tout donner pour ne jamais rendre la place",
            followHint: "Tu t'es accroché à cette place comme un chien. Le numéro un est revenu guéri, et il ne l'a jamais récupérée.",
            followEffects: [FDEffect(attr: .agilite, delta: 5), FDEffect(attr: .sangfroid, delta: 4), FDEffect(cond: "fatigue", delta: 8), FDEffect(cond: "confiance", delta: 5)],
