    "legend_horloger": [
        FDLegendStep(
            age: 18, place: "Terrain d'un club modeste",
            text: "Modrez a commencé dans un championnat où personne ne regardait, dans un pays en reconstruction, et il y est resté jusqu'à vingt-deux ans en refusant deux offres. Il disait qu'il avait besoin de jouer, pas de signer. On te fait la même offre trop tôt, et tout le monde te dit d'y aller.",
