    "legend_lion_atlas": [
        FDLegendStep(
            age: 18, place: "Aéroport",
            text: "Hadjri a quitté son pays à dix-huit ans, seul, sans parler la langue, pour un club européen de milieu de tableau qui ne lui garantissait rien. Sa famille était contre. Il a mis deux ans à jouer. Tu as exactement la même offre sur la table, et le même salon familial contre toi.",
