        FDLegendStep(
            age: 26, place: "Terrain, finale continentale",
            text: "Sa finale européenne : à vingt-six ans, il a joué cent vingt minutes avec un carton jaune dès la 15e, sans jamais reculer d'un duel. L'arbitre a dit après qu'il n'avait jamais vu ça. Tu prends un jaune à la 15e d'une finale, et l'adversaire l'a très bien vu.",
            followLabel: "Continuer à jouer chaque duel",
            followHint: "Tu as joué chaque duel malgré le jaune, pendant cent cinq minutes. L'arbitre n'a jamais ressorti son carton, et l'adversaire a fini par renoncer.",
            followEffects: [FDEffect(attr: .tacle, delta: 6), FDEffect(attr: .sangfroid, delta: 5), FDEffect(cond: "reputation", delta: 8), FDEffect(cond: "fatigue", delta: 9)],
            ownLabel: "Lever le pied pour finir le match",
            ownHint: "Tu as levé le pied pour finir la finale. Tu as fini le match sur le terrain, et ton milieu a été traversé toute la soirée.",
            ownEffects: [FDEffect(cond: "forme", delta: 5), FDEffect(rel: "coach", delta: -4), FDEffect(cond: "reputation", delta: -4)]),
        FDLegendStep(
            age: 28, place: "Vestiaire, finale internationale",
            text: "Sa finale de Coupe du monde a duré cent vingt minutes, et il l'a finie le visage en sang après un choc à la 100e, sans jamais demander à sortir. C'est cette image-là qui a fait sa légende, pas ses passes. Tu prends le même choc à la même minute, et le médecin est déjà sur le terrain.",
            followLabel: "Rester sur le terrain, comme lui",
            followHint: "Tu es resté, le visage en sang, jusqu'à la 120e. C'est cette image-là que le pays a gardée.",
            followEffects: [FDEffect(attr: .determination, delta: 7), FDEffect(cond: "reputation", delta: 10), FDEffect(cond: "forme", delta: -8), FDEffect(cond: "fatigue", delta: 12)],
            ownLabel: "Sortir, tu es sonné",
            ownHint: "Tu es sorti. C'était raisonnable, ton remplaçant a fini le match, et il n'y a pas d'image.",
            ownEffects: [FDEffect(cond: "forme", delta: 6), FDEffect(rel: "staff", delta: 5), FDEffect(cond: "reputation", delta: -5)]),
        FDLegendStep(
            age: 32, place: "Salon familial",
            text: "À trente-deux ans, il a arrêté du jour au lendemain, au sommet, en disant qu'il préférait partir un an trop tôt qu'un an trop tard. Le club était prêt à le prolonger trois ans. On vient de te faire cette proposition de prolongation, et tu es exactement à cet endroit-là.",
            followLabel: "Arrêter au sommet, comme lui",
            followHint: "Tu as arrêté au sommet, un an trop tôt selon tout le monde. C'est l'image qui reste, et c'est celle que tu as choisie.",
            followEffects: [FDEffect(cond: "reputation", delta: 8), FDEffect(cond: "moral", delta: 5), FDEffect(money: -200000)],
            ownLabel: "Prolonger trois ans de plus",
            ownHint: "Tu as prolongé trois ans. Tu as joué de moins en moins bien, et le stade a fini par soupirer quand tu entrais.",
            ownEffects: [FDEffect(money: 250000), FDEffect(cond: "reputation", delta: -6), FDEffect(cond: "fatigue", delta: 8)]),
    ],
    "legend_taureau": [
        FDLegendStep(
            age: 18, place: "Terrain, club de quartier",
            text: "Francescolo a signé pro à dix-huit ans dans un club qui jouait la relégation, en refusant deux grands clubs, parce qu'on lui garantissait de jouer avant-centre et rien d'autre. Il a marqué vingt buts la première année. On te propose la même chose ce matin, dans un club qui va lutter toute la saison.",
            followLabel: "Signer là où tu joueras avant-centre",
            followHint: "Tu as signé dans le club qui lutte, pour jouer avant-centre. Vingt buts, une saison à souffrir, et personne à qui laisser ta place.",
            followEffects: [FDEffect(attr: .tir, delta: 5), FDEffect(attr: .force, delta: 4), FDEffect(cond: "fatigue", delta: 8), FDEffect(cond: "reputation", delta: -3)],
            ownLabel: "Signer au grand club, même en rotation",
            ownHint: "Tu as signé au grand club. Tu t'entraînes avec les meilleurs, et tu es quatrième dans la hiérarchie.",
            ownEffects: [FDEffect(cond: "reputation", delta: 6), FDEffect(attr: .control, delta: 3), FDEffect(cond: "confiance", delta: -4)],
            followMove: "modeste",
            ownMove: "grand"),
        FDLegendStep(
            age: 22, place: "Terrain",
            text: "Aucun défenseur ne voulait l'affronter deux fois : il rendait chaque coup, immédiatement, et l'assumait. À vingt-deux ans, il a été suspendu six matchs pour ça, et il a dit qu'il recommencerait. Tu viens de prendre un coup de coude volontaire, hors du champ de l'arbitre.",
            followLabel: "Le rendre immédiatement, comme lui",
            followHint: "Tu l'as rendu tout de suite. Suspension, amende, et plus personne ne t'a touché de la saison.",
            followEffects: [FDEffect(attr: .force, delta: 5), FDEffect(cond: "reputation", delta: 6), FDEffect(rel: "coach", delta: -5), FDEffect(cond: "moral", delta: 4)],
            ownLabel: "Encaisser et jouer",
            ownHint: "Tu as encaissé sans réagir. L'arbitre n'a rien vu, et il a recommencé vingt minutes plus tard.",
            ownEffects: [FDEffect(attr: .sangfroid, delta: 5), FDEffect(rel: "coach", delta: 5), FDEffect(cond: "moral", delta: -4)]),
        FDLegendStep(
            age: 24, place: "Bureau de l'agent",
            text: "À vingt-quatre ans, Francescolo a signé dans le club le plus dur du continent, celui dont personne ne voulait, parce qu'on lui a dit qu'il n'y survivrait pas. Il y a passé sept ans. On te dit exactement la même chose ce matin, à propos du même genre de club.",
            followLabel: "Y aller parce qu'on te dit que tu n'y survivras pas",
            followHint: "Tu es allé là où personne ne voulait aller. Sept ans dans le club le plus dur du continent, et plus rien ne t'impressionne.",
            followEffects: [FDEffect(attr: .force, delta: 6), FDEffect(attr: .determination, delta: 5), FDEffect(cond: "fatigue", delta: 9), FDEffect(cond: "reputation", delta: 7)],
            ownLabel: "Choisir un club où tu seras protégé",
            ownHint: "Tu as choisi un club où tu es protégé. Tu joues bien, tranquille, et tu ne sauras jamais ce que tu valais là-bas.",
            ownEffects: [FDEffect(cond: "moral", delta: 6), FDEffect(cond: "forme", delta: 5), FDEffect(attr: .force, delta: -2)],
            followMove: "grand",
            ownMove: "modeste"),
        FDLegendStep(
            age: 26, place: "Terrain, finale continentale",
            text: "Sa finale, il l'a jouée contre le meilleur défenseur du monde et il a passé quatre-vingt-dix minutes à le chercher physiquement, jusqu'à le faire sortir sur blessure à la 70e. Il a marqué à la 75e. En face de toi ce soir, il y a exactement ce genre de défenseur.",
            followLabel: "L'user physiquement toute la soirée",
            followHint: "Tu l'as usé pendant soixante-dix minutes, jusqu'à ce qu'il sorte. Tu as marqué cinq minutes après, et la presse a parlé d'autre chose.",
            followEffects: [FDEffect(attr: .force, delta: 6), FDEffect(attr: .tir, delta: 4), FDEffect(cond: "reputation", delta: 6), FDEffect(cond: "fatigue", delta: 11)],
            ownLabel: "Jouer dans son dos plutôt que contre lui",
            ownHint: "Tu as joué dans son dos, sans jamais l'affronter. Il t'a annulé quand même, proprement.",
            ownEffects: [FDEffect(attr: .placement, delta: 5), FDEffect(attr: .vitesse, delta: 3), FDEffect(cond: "reputation", delta: -3)]),
        FDLegendStep(
            age: 29, place: "Terrain, match de championnat",
            text: "Son record : à vingt-neuf ans, quatre buts en un match contre le meilleur défenseur du championnat, après lui avoir dit avant le coup d'envoi qu'il en mettrait trois. Il en a mis quatre. En face, ce soir, il y a exactement ce défenseur-là.",
            followLabel: "Lui annoncer avant le coup d'envoi",
            followHint: "Tu lui as annoncé le nombre de buts avant le coup d'envoi, et tu en as mis un de plus. Il ne s'en est jamais remis.",
            followEffects: [FDEffect(attr: .tir, delta: 6), FDEffect(cond: "confiance", delta: 8), FDEffect(cond: "reputation", delta: 9), FDEffect(rel: "media", delta: 4)],
            ownLabel: "Le laisser venir sans rien dire",
            ownHint: "Tu n'as rien dit. Tu as marqué deux fois, proprement, et il t'a serré la main à la fin.",
            ownEffects: [FDEffect(attr: .tir, delta: 4), FDEffect(rel: "vestiaire", delta: 5), FDEffect(cond: "reputation", delta: -3)]),
        FDLegendStep(
            age: 31, place: "Zone mixte",
            text: "À trente et un ans, après un carton rouge en Coupe du monde qui a éliminé son pays, il a assumé publiquement sans jamais s'excuser, en disant qu'il avait fait ce qu'il fallait. Le pays s'est divisé pendant vingt ans. Tu viens exactement de vivre ça, et les micros t'attendent.",
            followLabel: "Assumer sans t'excuser, comme lui",
            followHint: "Tu as assumé sans t'excuser, devant tout le pays. La moitié te déteste, l'autre moitié t'a mis sur un piédestal.",
            followEffects: [FDEffect(cond: "reputation", delta: 6), FDEffect(rel: "fans", delta: 4), FDEffect(rel: "media", delta: -6), FDEffect(cond: "moral", delta: 5)],
            ownLabel: "T'excuser auprès du pays",
            ownHint: "Tu t'es excusé publiquement. Le pays a pardonné, et deux coéquipiers ont trouvé que tu t'écrasais.",
            ownEffects: [FDEffect(rel: "media", delta: 6), FDEffect(rel: "fans", delta: 5), FDEffect(cond: "confiance", delta: -5)]),
    ],
    "legend_samourai": [
        FDLegendStep(
            age: 18, place: "Aéroport",
            text: "Nakada est parti à dix-huit ans dans un pays dont il ne parlait pas un mot, avec une seule règle qu'il s'était fixée : ne jamais rentrer chez lui avant d'avoir joué cent matchs. Il a tenu quatre ans sans revoir sa famille. La même porte s'ouvre pour toi, et tes parents ne parlent pas non plus la langue.",
            followLabel: "Partir et ne pas rentrer avant d'avoir réussi",
            followHint: "Tu es parti sans revenir pendant quatre ans. Cent matchs, une langue apprise, et quatre Noëls manqués.",
            followEffects: [FDEffect(attr: .determination, delta: 7), FDEffect(cond: "reputation", delta: 6), FDEffect(rel: "famille", delta: -8), FDEffect(cond: "moral", delta: -5)],
            ownLabel: "Partir en gardant le lien avec les tiens",
            ownHint: "Tu es parti en rentrant chaque trêve. Tu as gardé ta famille, et tu as mis deux ans de plus à t'intégrer.",
            ownEffects: [FDEffect(rel: "famille", delta: 7), FDEffect(cond: "moral", delta: 5), FDEffect(attr: .determination, delta: -2)],
            followMove: "etranger",
            ownMove: "etranger"),
        FDLegendStep(
            age: 22, place: "Salle de réunion",
            text: "Sa rigueur était totale : à vingt-deux ans, il a demandé à son club un planning écrit de chaque journée pour les deux saisons à venir, et il l'a suivi à la lettre. Le staff l'a pris pour un maniaque avant de comprendre. Le tien te regarde bizarrement pendant que tu poses la même question.",
            followLabel: "Imposer ta rigueur, comme lui",
            followHint: "Tu as obtenu ton planning à la minute et tu t'y es tenu deux ans. Le staff t'a trouvé rigide, et tu n'as jamais manqué une séance.",
            followEffects: [FDEffect(attr: .determination, delta: 5), FDEffect(cond: "forme", delta: 6), FDEffect(rel: "vestiaire", delta: -4), FDEffect(cond: "moral", delta: -3)],
            ownLabel: "T'adapter au fonctionnement du club",
            ownHint: "Tu t'es adapté au fonctionnement du club. Tout le monde t'a trouvé facile à vivre, et ta préparation est celle de tout le monde.",
            ownEffects: [FDEffect(rel: "vestiaire", delta: 6), FDEffect(rel: "staff", delta: 5), FDEffect(cond: "forme", delta: -2)]),
        FDLegendStep(
            age: 24, place: "Bureau du club",
            text: "À vingt-quatre ans, Nakada a quitté un grand club où il était remplaçant pour un club moyen où il jouait tout, en divisant son salaire par deux. Sa fédération lui a demandé de rester dans le grand club pour l'image du pays. Tu es exactement dans cette situation.",
            followLabel: "Partir jouer, même pour moins",
            followHint: "Tu es parti jouer dans le club moyen, pour moitié moins. Ta fédération l'a mal pris, et tu as retrouvé un football.",
            followEffects: [FDEffect(cond: "forme", delta: 6), FDEffect(attr: .control, delta: 4), FDEffect(money: -80000), FDEffect(cond: "reputation", delta: -3)],
            ownLabel: "Rester pour l'image du pays",
            ownHint: "Tu es resté remplaçant dans le grand club, pour l'image. Le maillot est superbe, et tu as joué neuf cents minutes en deux ans.",
            ownEffects: [FDEffect(cond: "reputation", delta: 6), FDEffect(money: 100000), FDEffect(cond: "confiance", delta: -6)],
            followMove: "modeste"),
        FDLegendStep(
            age: 26, place: "Terrain, phase de groupes internationale",
            text: "Le but qui a fait sa légende, il l'a marqué en Coupe du monde d'une frappe de trente mètres qu'il avait travaillée mille fois seul, après les séances, pendant six ans. Il a dit ensuite qu'il l'avait mise exactement là où il visait. Le ballon te revient à trente mètres, ce soir.",
            followLabel: "Frapper, tu l'as travaillé mille fois",
            followHint: "Tu as frappé de trente mètres. Six ans de séances supplémentaires sont passés dans ce ballon-là.",
            followEffects: [FDEffect(attr: .tir, delta: 6), FDEffect(cond: "reputation", delta: 9), FDEffect(cond: "confiance", delta: 6), FDEffect(cond: "fatigue", delta: 5)],
            ownLabel: "Donner le ballon et construire",
            ownHint: "Tu as donné le ballon, proprement. L'action a continué, et personne n'a marqué.",
            ownEffects: [FDEffect(attr: .passe, delta: 4), FDEffect(rel: "vestiaire", delta: 4), FDEffect(cond: "reputation", delta: -4)]),
        FDLegendStep(
            age: 28, place: "Terrain, phase finale internationale",
            text: "Le carton qui a changé sa carrière : à vingt-huit ans, un rouge en Coupe du monde pour avoir protesté, alors qu'il n'avait jamais reçu le moindre carton en dix ans. Il s'est excusé publiquement le soir même. L'arbitre vient de prendre une décision scandaleuse contre toi, en Coupe du monde.",
            followLabel: "Protester, pour une fois",
            followHint: "Tu as protesté, pour la première fois de ta carrière. Rouge, et une image de toi que personne ne reconnaissait.",
            followEffects: [FDEffect(cond: "reputation", delta: 5), FDEffect(cond: "moral", delta: -6), FDEffect(rel: "media", delta: -5), FDEffect(attr: .determination, delta: 4)],
            ownLabel: "Encaisser sans un mot, comme toujours",
            ownHint: "Tu as encaissé sans un mot, comme depuis dix ans. L'arbitre n'a rien changé, et ton dossier disciplinaire est resté vierge.",
            ownEffects: [FDEffect(attr: .sangfroid, delta: 6), FDEffect(rel: "media", delta: 6), FDEffect(cond: "moral", delta: -3)]),
        FDLegendStep(
            age: 30, place: "Salon familial",
            text: "À trente ans, il est rentré au pays pour finir sa carrière dans le club de sa ville, en refusant des offres bien plus riches, pour que le football de son pays profite de ce qu'il avait appris. Le club de ta ville vient d'appeler, et l'écart de salaire est considérable.",
            followLabel: "Rentrer transmettre chez toi",
            followHint: "Tu es rentré finir chez toi. Le championnat de ton pays a gagné dix ans d'expérience, et ton compte en a perdu beaucoup.",
            followEffects: [FDEffect(rel: "fans", delta: 9), FDEffect(cond: "moral", delta: 7), FDEffect(money: -180000), FDEffect(cond: "reputation", delta: -4)],
            ownLabel: "Rester au plus haut niveau",
            ownHint: "Tu es resté au plus haut niveau jusqu'au bout. C'est mieux payé, et ton pays a regardé de loin.",
            ownEffects: [FDEffect(money: 220000), FDEffect(cond: "reputation", delta: 5), FDEffect(rel: "fans", delta: -5)],
            followMove: "retour"),
    ],
    "legend_aigle_carthage": [
        FDLegendStep(
            age: 19, place: "Terrain, championnat national",
            text: "Chikhoui a marqué dans tous les stades de son continent avant d'aller ailleurs. À dix-neuf ans, il a refusé une offre européenne moyenne en disant qu'il voulait d'abord tout gagner chez lui. Il l'a fait en trois ans. Une offre européenne moyenne vient d'arriver, et personne ne comprendrait un refus.",
            followLabel: "Tout gagner chez toi d'abord",
            followHint: "Tu as refusé l'Europe pour tout gagner chez toi. Trois titres, un continent conquis, et trois ans de plus avant de partir.",
            followEffects: [FDEffect(cond: "reputation", delta: 6), FDEffect(rel: "fans", delta: 8), FDEffect(cond: "confiance", delta: 5), FDEffect(money: -40000)],
            ownLabel: "Partir en Europe maintenant",
            ownHint: "Tu es parti en Europe tout de suite. Le niveau est plus haut, et tu n'as rien gagné nulle part.",
            ownEffects: [FDEffect(attr: .control, delta: 4), FDEffect(cond: "reputation", delta: 4), FDEffect(rel: "fans", delta: -5)],
            ownMove: "etranger"),
        FDLegendStep(
            age: 21, place: "Bureau de l'agent",
            text: "À vingt et un ans, Chikhoui a signé en Europe dans un club de milieu de tableau qui lui garantissait de jouer, plutôt que dans un grand club qui le voulait pour le banc. Le pays entier lui a reproché ce choix. Tu as exactement ces deux dossiers, et tout le monde a un avis.",
            followLabel: "Choisir le club où tu joueras",
            followHint: "Tu as choisi le club où tu joues. Le pays t'a reproché de viser bas, et tu as disputé cent matchs en trois ans.",
            followEffects: [FDEffect(cond: "forme", delta: 6), FDEffect(attr: .tir, delta: 4), FDEffect(cond: "reputation", delta: -4), FDEffect(cond: "confiance", delta: 5)],
            ownLabel: "Choisir le grand club, même sur le banc",
            ownHint: "Tu as choisi le grand club. Le pays était fier, et tu as passé deux ans à t'échauffer.",
            ownEffects: [FDEffect(cond: "reputation", delta: 7), FDEffect(rel: "fans", delta: 6), FDEffect(cond: "confiance", delta: -6)],
            followMove: "modeste",
            ownMove: "grand"),
        FDLegendStep(
            age: 23, place: "Vestiaire, sélection",
            text: "À vingt-trois ans, il a été le seul joueur de son pays à s'imposer dans un grand championnat, et il a passé chaque rassemblement à ramener ce qu'il apprenait au groupe national. Ça lui prenait toutes ses soirées de sélection. Le sélectionneur t'a demandé exactement ça hier soir.",
            followLabel: "Transmettre à chaque rassemblement",
            followHint: "Tu as passé chaque rassemblement à transmettre ce que tu apprenais. Le groupe a franchi un cap, et tu n'as jamais eu une soirée à toi.",
            followEffects: [FDEffect(attr: .leadership, delta: 5), FDEffect(rel: "vestiaire", delta: 7), FDEffect(cond: "fatigue", delta: 8)],
            ownLabel: "Te concentrer sur tes propres matchs",
            ownHint: "Tu t'es concentré sur toi. Tu as été excellent, et le groupe est resté ce qu'il était.",
            ownEffects: [FDEffect(cond: "forme", delta: 5), FDEffect(cond: "confiance", delta: 4), FDEffect(rel: "vestiaire", delta: -4)]),
        FDLegendStep(
            age: 27, place: "Terrain, finale continentale",
            text: "Sa finale de coupe continentale reste le sommet du football de son pays : il a marqué deux fois en jouant avec une déchirure, et il n'a plus jamais été le même joueur après. Il a dit que ça valait le coup. Tu es dans ce vestiaire, avec cette déchirure, et le médecin a dit non.",
            followLabel: "Jouer la finale malgré la déchirure",
            followHint: "Tu as joué avec la déchirure, et tu as marqué deux fois. Tu n'as plus jamais été le même après, et le pays s'en souvient chaque année.",
            followEffects: [FDEffect(cond: "reputation", delta: 11), FDEffect(rel: "fans", delta: 10), FDEffect(cond: "forme", delta: -14), FDEffect(attr: .vitesse, delta: -3)],
            ownLabel: "Écouter le médecin",
            ownHint: "Tu as écouté le médecin. La finale s'est jouée sans toi, et tu es entier.",
            ownEffects: [FDEffect(cond: "forme", delta: 7), FDEffect(rel: "staff", delta: 6), FDEffect(cond: "reputation", delta: -6)]),
        FDLegendStep(
            age: 29, place: "Terrain, match de qualification",
            text: "Le but dont son pays parle encore : à vingt-neuf ans, une reprise de volée à la 94e minute qui a envoyé le pays à sa première grande compétition depuis vingt ans. Il jouait avec une entorse. La même situation exactement, avec la même cheville en vrac.",
            followLabel: "Jouer la fin de match sur ta cheville",
            followHint: "Tu as fini le match sur une cheville en vrac, et tu as mis la volée à la 94e. Ton pays y était pour la première fois depuis vingt ans.",
            followEffects: [FDEffect(attr: .tir, delta: 6), FDEffect(cond: "reputation", delta: 12), FDEffect(rel: "fans", delta: 11), FDEffect(cond: "forme", delta: -9)],
            ownLabel: "Demander le changement",
            ownHint: "Tu as demandé le changement. Ton remplaçant a fait ce qu'il a pu, et le pays a attendu quatre ans de plus.",
            ownEffects: [FDEffect(cond: "forme", delta: 7), FDEffect(rel: "staff", delta: 5), FDEffect(rel: "fans", delta: -7)]),
        FDLegendStep(
            age: 31, place: "Bureau de la fédération",
            text: "À trente et un ans, il a mis toute sa fortune et son nom dans une académie chez lui, qui forme aujourd'hui la moitié de la sélection nationale. Ça lui a coûté presque tout ce qu'il avait gagné. On te propose exactement ce projet, avec le même budget à sortir.",
            followLabel: "Mettre ta fortune dans l'académie",
            followHint: "Tu as mis presque tout ce que tu avais dans l'académie. Elle forme aujourd'hui la moitié de la sélection, et ton compte est à sec.",
            followEffects: [FDEffect(money: -400000), FDEffect(rel: "fans", delta: 10), FDEffect(cond: "moral", delta: 8), FDEffect(cond: "reputation", delta: 6)],
            ownLabel: "Garder ton argent",
            ownHint: "Tu as gardé ton argent. C'est ton droit, tu es à l'abri, et l'académie n'existe pas.",
            ownEffects: [FDEffect(money: 100000), FDEffect(rel: "fans", delta: -6), FDEffect(cond: "moral", delta: -4)]),
    ],
    "legend_viking": [
        FDLegendStep(
            age: 18, place: "Bureau du directeur sportif",
            text: "Ibrahimson a annoncé à dix-huit ans, devant le directeur sportif d'un club moyen, qu'il serait le meilleur joueur du monde. Personne n'a ri, parce qu'il l'a dit sans sourire. Il a signé et il a marqué vingt buts. Le même bureau, le même contrat, et la même question sur tes ambitions.",
            followLabel: "Annoncer tes ambitions sans trembler",
            followHint: "Tu as annoncé que tu serais le meilleur du monde, sans sourire. Le club a adoré, la presse s'en est emparée, et il a fallu assumer.",
            followEffects: [FDEffect(cond: "confiance", delta: 8), FDEffect(cond: "reputation", delta: 7), FDEffect(rel: "media", delta: 5), FDEffect(rel: "vestiaire", delta: -4)],
            ownLabel: "Rester modeste et travailler",
            ownHint: "Tu es resté modeste. Personne n'a rien à te ressortir, et personne ne t'a remarqué non plus.",
            ownEffects: [FDEffect(rel: "vestiaire", delta: 6), FDEffect(rel: "coach", delta: 5), FDEffect(cond: "reputation", delta: -4)]),
        FDLegendStep(
            age: 21, place: "Bureau du club",
            text: "À vingt et un ans, Ibrahimson a été vendu dans un pays qu'il ne connaissait pas, et il a exigé que le club paie aussi le déménagement de toute sa famille. Le club a accepté en riant. Ton transfert est bouclé, et tu peux poser cette condition ou pas.",
            followLabel: "Exiger que ta famille vienne avec toi",
            followHint: "Tu as exigé que le club installe toute ta famille. Ils ont ri, ils ont payé, et tu n'as jamais été seul là-bas.",
            followEffects: [FDEffect(rel: "famille", delta: 9), FDEffect(cond: "moral", delta: 7), FDEffect(rel: "president", delta: -4)],
            ownLabel: "Partir seul et t'adapter",
            ownHint: "Tu es parti seul. Tu t'es adapté, plus vite que prévu, et les six premiers mois ont été très longs.",
            ownEffects: [FDEffect(attr: .determination, delta: 5), FDEffect(cond: "moral", delta: -5), FDEffect(rel: "president", delta: 4)]),
        FDLegendStep(
            age: 23, place: "Zone mixte",
            text: "Il a changé de club six fois en quinze ans, à chaque fois pour un rival direct, et à chaque fois en disant que c'était eux qui avaient de la chance. Le premier de ces transferts, à vingt-trois ans, lui a coûté un stade entier. Tu as exactement cette offre du rival sur la table.",
            followLabel: "Signer chez le rival et l'assumer",
            followHint: "Tu as signé chez le rival et tu l'as assumé au micro. Un stade entier te siffle à vie, et tu as gagné trois titres.",
            followEffects: [FDEffect(cond: "reputation", delta: 8), FDEffect(money: 150000), FDEffect(rel: "fans", delta: -10), FDEffect(cond: "confiance", delta: 6)],
            ownLabel: "Refuser par respect pour tes supporters",
            ownHint: "Tu as refusé le rival. Ton virage a chanté ton nom pendant six mois, et tu n'as rien gagné cette année-là.",
            ownEffects: [FDEffect(rel: "fans", delta: 9), FDEffect(cond: "moral", delta: 5), FDEffect(money: -60000), FDEffect(cond: "reputation", delta: -4)],
            followMove: "rival"),
        FDLegendStep(
            age: 25, place: "Terrain, match de championnat",
            text: "Le geste qui a fait sa réputation : à vingt-cinq ans, un contrôle du dos suivi d'une frappe en pivot, dans un match de championnat, expliqué ensuite par une phrase restée célèbre sur le fait qu'il ne s'entraînait pas à ça. Le ballon arrive haut dans ton dos, et le gardien est sorti.",
            followLabel: "Tenter le geste sans réfléchir",
            followHint: "Tu as tenté le contrôle du dos et la frappe en pivot. Le stade s'est levé, et la vidéo tourne encore.",
            followEffects: [FDEffect(attr: .agilite, delta: 6), FDEffect(attr: .tir, delta: 5), FDEffect(cond: "reputation", delta: 10), FDEffect(cond: "confiance", delta: 6)],
            ownLabel: "Amortir et jouer proprement",
            ownHint: "Tu as amorti et joué proprement. C'était le bon choix, et personne n'a filmé quoi que ce soit.",
            ownEffects: [FDEffect(attr: .control, delta: 5), FDEffect(rel: "coach", delta: 4), FDEffect(cond: "reputation", delta: -4)]),
        FDLegendStep(
            age: 28, place: "Terrain, match international",
            text: "Le geste qui a fait sa légende : un retourné acrobatique de trente-cinq mètres, en sélection, alors qu'il aurait pu contrôler tranquillement. Il a dit ensuite qu'il n'avait pas hésité une seconde. Le ballon revient sur toi, de dos, à trente-cinq mètres du but.",
            followLabel: "Tenter le retourné, comme lui",
            followHint: "Tu as tenté le retourné de trente-cinq mètres. C'est le genre de geste qu'on repasse pendant vingt ans, dans un sens ou dans l'autre.",
            followEffects: [FDEffect(attr: .tir, delta: 6), FDEffect(attr: .agilite, delta: 5), FDEffect(cond: "reputation", delta: 10), FDEffect(cond: "fatigue", delta: 6)],
            ownLabel: "Contrôler et jouer simple",
            ownHint: "Tu as contrôlé proprement et donné le ballon. Choix juste, personne n'en parlera jamais.",
            ownEffects: [FDEffect(attr: .control, delta: 5), FDEffect(rel: "coach", delta: 4), FDEffect(cond: "reputation", delta: -4)]),
        FDLegendStep(
            age: 34, place: "Salle de conférence",
            text: "À trente-quatre ans, revenu de blessure quand tout le monde le disait fini, il a déclaré qu'il n'était pas revenu pour finir mais pour gagner. Il a gagné. On te tend le micro pour ton retour, dans exactement le même contexte.",
            followLabel: "Annoncer que tu reviens pour gagner",
            followHint: "Tu as annoncé que tu revenais pour gagner. Tout le monde a souri, et tu as gagné.",
            followEffects: [FDEffect(cond: "confiance", delta: 7), FDEffect(cond: "reputation", delta: 8), FDEffect(cond: "fatigue", delta: 7), FDEffect(rel: "media", delta: 5)],
            ownLabel: "Rester prudent sur ton retour",
            ownHint: "Tu es resté prudent. Tu es revenu doucement, sans promesse, et sans que personne y prête attention.",
            ownEffects: [FDEffect(cond: "forme", delta: 6), FDEffect(rel: "staff", delta: 5), FDEffect(cond: "reputation", delta: -4)]),
    ],
    "legend_panthere": [
        FDLegendStep(
            age: 18, place: "Terrain, club formateur",
            text: "Farias a été repéré à dix-huit ans sur un terrain en terre battue, et il a exigé que son petit club touche un vrai pourcentage sur son transfert, ce qu'aucun joueur ne faisait à l'époque. Le club en vit encore. Ton club formateur est en difficulté, et personne ne t'a demandé de le défendre.",
            followLabel: "Exiger une part pour ton club formateur",
            followHint: "Tu as exigé une part pour ton club formateur. Il en vit encore, et ton transfert a mis trois mois de plus à se faire.",
            followEffects: [FDEffect(rel: "president", delta: 7), FDEffect(rel: "fans", delta: 6), FDEffect(money: -50000), FDEffect(cond: "reputation", delta: 4)],
