            followEffects: [FDEffect(rel: "fans", delta: 8), FDEffect(cond: "reputation", delta: 5), FDEffect(money: -60000), FDEffect(rel: "president", delta: -4)],
            ownLabel: "Signer sans conditions",
            ownHint: "Tu as signé sans conditions. Le transfert record est passé, et ton club formateur a fermé deux ans plus tard.",
            ownEffects: [FDEffect(money: 200000), FDEffect(cond: "reputation", delta: 7), FDEffect(rel: "fans", delta: -6)],
            followMove: "grand",
            ownMove: "grand"),
        FDLegendStep(
            age: 26, place: "Terrain, finale internationale",
            text: "Sa finale de Coupe du monde est celle de la rédemption : quatre ans plus tôt il avait disparu de la plus grande finale de sa vie sans qu'on sache pourquoi, et il est revenu pour marquer deux fois. Ce soir tu joues la finale que tu as manquée il y a quatre ans, dans les mêmes conditions.",
            followLabel: "Tout mettre dans cette finale",
            followHint: "Tu as tout mis dans cette finale. Deux buts, et quatre ans de silence effacés en quatre-vingt-dix minutes.",
            followEffects: [FDEffect(attr: .tir, delta: 6), FDEffect(cond: "reputation", delta: 12), FDEffect(cond: "confiance", delta: 8), FDEffect(cond: "fatigue", delta: 11)],
            ownLabel: "Jouer sans y mettre le poids du passé",
            ownHint: "Tu as joué sans y mettre le passé. Match correct, victoire collective, et une question qui reste ouverte.",
            ownEffects: [FDEffect(attr: .sangfroid, delta: 5), FDEffect(cond: "moral", delta: 5), FDEffect(cond: "reputation", delta: -4)]),
        FDLegendStep(
            age: 27, place: "Terrain, huitième de finale internationale",
            text: "Sa série : à vingt-sept ans, il a marqué dans sept matchs consécutifs de Coupe du monde, un record que personne n'a battu. Le dernier, il l'a marqué avec les ligaments déjà touchés, sans le dire. Tu en es à six matchs, et ton genou t'a lâché à l'échauffement.",
            followLabel: "Jouer pour prolonger la série",
            followHint: "Tu as joué pour prolonger la série, avec les ligaments déjà touchés. Sept matchs de suite, et une saison entière perdue derrière.",
            followEffects: [FDEffect(attr: .tir, delta: 5), FDEffect(cond: "reputation", delta: 11), FDEffect(cond: "forme", delta: -13), FDEffect(cond: "fatigue", delta: 10)],
            ownLabel: "T'arrêter à six",
            ownHint: "Tu t'es arrêté à six. Le record est resté à un autre, et tu as joué la saison suivante.",
            ownEffects: [FDEffect(cond: "forme", delta: 9), FDEffect(rel: "staff", delta: 6), FDEffect(cond: "reputation", delta: -6)]),
        FDLegendStep(
            age: 29, place: "Cabinet médical",
            text: "Ses genoux l'ont lâché à vingt-neuf ans, après trois opérations. On lui a proposé d'arrêter ; il a repris et il a rejoué quatre saisons, moins vite, en devenant un autre joueur. Le chirurgien te tient exactement ce discours ce matin, avec le même dossier sur la table.",
            followLabel: "Revenir et te réinventer",
