    ],
    "legend_divin": [
        FDLegendStep(
            age: 19, place: "Terrain d'entraînement",
            text: "Baggini avait un jeu de tête et une frappe, et il a passé sa jeunesse à travailler la seule chose qui lui manquait : le pied gauche, deux heures par jour pendant trois ans. À dix-neuf ans il ne s'en servait jamais ; à vingt-deux, personne ne savait plus de quel pied il jouait.",
            followLabel: "Passer trois ans sur ton mauvais pied",
            followHint: "Tu as passé trois ans à travailler ton mauvais pied, deux heures par jour. Aujourd'hui, personne ne sait de quel pied tu joues.",
            followEffects: [FDEffect(attr: .tir, delta: 5), FDEffect(attr: .control, delta: 4), FDEffect(cond: "fatigue", delta: 8), FDEffect(cond: "moral", delta: -3)],
