    "legend_pharaon": [
        FDLegendStep(
            age: 18, place: "Bureau du directeur sportif",
            text: "Salaheddin est parti de son village pour un club européen à dix-huit ans, et il y a été un échec complet pendant deux ans : dix matchs, zéro but, et un retour au pays annoncé partout comme définitif. Il est reparti quand même. Ta première expérience à l'étranger tourne exactement comme ça.",
            followLabel: "Repartir à l'étranger malgré l'échec",
