            followLabel: "Changer de côté et tout réapprendre",
            followHint: "Tu as changé de côté et tout réappris pendant une saison. Depuis, tu finis chaque action du même pied, et ça se voit sur ta ligne de buts.",
            followEffects: [FDEffect(attr: .tir, delta: 6), FDEffect(attr: .placement, delta: 5), FDEffect(cond: "confiance", delta: -4), FDEffect(cond: "fatigue", delta: 7)],
            ownLabel: "Rester sur ton côté naturel",
            ownHint: "Tu es resté sur ton côté. Tu centres bien, tu débordes bien, et tu marques toujours autant qu'avant.",
            ownEffects: [FDEffect(attr: .centres, delta: 5), FDEffect(attr: .vitesse, delta: 3), FDEffect(attr: .tir, delta: -1)]),
        FDLegendStep(
