    "legend_architecte": [
        FDLegendStep(
            age: 18, place: "Terrain d'entraînement",
            text: "Hernando n'a jamais couru vite et il ne l'a jamais caché : il a passé sa jeunesse à travailler l'orientation du corps, pour savoir où aller avant que le ballon arrive. On lui a répété qu'il ne tiendrait jamais physiquement. Ton préparateur vient de te dire exactement la même chose.",
            followLabel: "Travailler la lecture plutôt que la course",
