    "legend_condor": [
        FDLegendStep(
            age: 18, place: "Terrain, club de quartier",
            text: "Canizza pouvait faire le geste du siècle un dimanche et disparaître le suivant. À dix-huit ans, un coach lui a proposé un cadre très strict pour canaliser ça ; il a refusé et il a signé ailleurs. Ton coach te propose exactement ce cadre, avec des règles écrites.",
