            ownLabel: "Partir en Europe maintenant",
            ownHint: "Tu es parti en Europe tout de suite. Le niveau est plus haut, et personne là-bas ne comprend ce que tu essaies de faire.",
            ownEffects: [FDEffect(cond: "reputation", delta: 7), FDEffect(money: 120000), FDEffect(cond: "confiance", delta: -4)],
            ownMove: "etranger"),
        FDLegendStep(
            age: 23, place: "Bureau du coach",
            text: "À vingt-trois ans, on lui a interdit ses gestes en match, sous peine de banc. Il en a fait un le week-end suivant, il a marqué, et il est resté sur le banc trois semaines quand même. Ton coach vient de te faire exactement la même annonce ce matin.",
            followLabel: "Le faire quand même",
            followHint: "Tu as fait le geste le week-end suivant. Tu as marqué, tu as pris trois semaines de banc, et le stade s'en souvient encore.",
            followEffects: [FDEffect(attr: .dribble, delta: 6), FDEffect(cond: "reputation", delta: 7), FDEffect(rel: "coach", delta: -7), FDEffect(cond: "confiance", delta: 6)],
            ownLabel: "Respecter l'interdiction",
            ownHint: "Tu as respecté l'interdiction. Tu as joué tous les matchs, sagement, et personne n'a filmé quoi que ce soit.",
            ownEffects: [FDEffect(rel: "coach", delta: 6), FDEffect(cond: "forme", delta: 4), FDEffect(attr: .dribble, delta: -3)]),
        FDLegendStep(
            age: 27, place: "Terrain, phase de groupes internationale",
            text: "Son geste de légende, il l'a fait en Coupe du monde contre l'une des meilleures nations du monde : deux joueurs éliminés d'un même mouvement, dans son propre camp, à 1-1. Il aurait pu tout perdre. Tu es exactement dans ta moitié de terrain, avec deux joueurs sur toi.",
            followLabel: "Tenter le geste dans ton camp",
            followHint: "Tu as tenté ton geste dans ton propre camp, en Coupe du monde. Deux joueurs éliminés, un stade en apnée, et une image pour toujours.",
            followEffects: [FDEffect(attr: .dribble, delta: 7), FDEffect(attr: .agilite, delta: 5), FDEffect(cond: "reputation", delta: 11), FDEffect(rel: "coach", delta: -4)],
            ownLabel: "Jouer simple et remonter le ballon",
            ownHint: "Tu as joué simple. Le ballon est remonté proprement, et le match s'est terminé sur un nul.",
            ownEffects: [FDEffect(attr: .passe, delta: 5), FDEffect(rel: "coach", delta: 5), FDEffect(cond: "reputation", delta: -4)]),
        FDLegendStep(
            age: 29, place: "Terrain, match amical international",
            text: "Le geste qui porte son nom : à vingt-neuf ans, un dégagement acrobatique en plongeant tête la première, sur une ligne de but, dans un match amical qui ne comptait pas. Le monde entier l'a vu. Le ballon file vers ta ligne, dans un match qui n'a aucun enjeu.",
            followLabel: "Faire le geste, même sans enjeu",
            followHint: "Tu as fait le geste acrobatique dans un match sans enjeu. Il porte ton nom aujourd'hui, et personne ne se souvient du score.",
            followEffects: [FDEffect(attr: .agilite, delta: 7), FDEffect(cond: "reputation", delta: 11), FDEffect(cond: "fatigue", delta: 6), FDEffect(rel: "coach", delta: -3)],
            ownLabel: "Dégager simplement",
            ownHint: "Tu as dégagé simplement. Le ballon est parti en touche, et le match amical s'est terminé sur un 0-0.",
            ownEffects: [FDEffect(attr: .placement, delta: 4), FDEffect(rel: "coach", delta: 4), FDEffect(cond: "reputation", delta: -5)]),
        FDLegendStep(
            age: 33, place: "Terrain, club de sa ville",
            text: "À trente-trois ans, il est retourné jouer dans le club de son quartier, en cinquième division, en refusant deux offres professionnelles, pour finir là où il avait commencé. Il a joué jusqu'à quarante ans. Le club de ton quartier vient de te proposer la même chose.",
            followLabel: "Retourner jouer dans ton quartier",
            followHint: "Tu es retourné jouer dans ton quartier, en cinquième division. Personne n'a compris, et tu as joué jusqu'à quarante ans.",
            followEffects: [FDEffect(cond: "moral", delta: 8), FDEffect(rel: "fans", delta: 8), FDEffect(money: -90000), FDEffect(cond: "reputation", delta: -6)],
            ownLabel: "Continuer chez les professionnels",
            ownHint: "Tu as continué chez les professionnels. Deux saisons correctes, bien payées, loin de chez toi.",
            ownEffects: [FDEffect(money: 120000), FDEffect(cond: "reputation", delta: 4), FDEffect(cond: "moral", delta: -4)]),
    ],
    "legend_ours": [
        FDLegendStep(
            age: 18, place: "Bureau du directeur sportif",
            text: "Sukar a quitté son pays à dix-huit ans en pleine période de guerre, sans savoir s'il pourrait revenir, pour signer dans un club étranger de milieu de tableau. Il a mis quatre ans à revoir sa famille. Ton pays traverse une période difficile, et l'offre étrangère expire vendredi.",
            followLabel: "Partir sans savoir quand tu reviendras",
            followHint: "Tu es parti sans savoir quand tu reverrais les tiens. Ça a duré quatre ans, et ta carrière n'aurait pas existé autrement.",
            followEffects: [FDEffect(attr: .determination, delta: 7), FDEffect(cond: "reputation", delta: 5), FDEffect(rel: "famille", delta: -7), FDEffect(cond: "moral", delta: -5)],
            ownLabel: "Rester avec les tiens",
            ownHint: "Tu es resté avec les tiens, dans un championnat à l'arrêt. Tu as bien fait pour eux, et tu as perdu quatre ans de carrière.",
