            followEffects: [FDEffect(attr: .tir, delta: 6), FDEffect(attr: .control, delta: 5), FDEffect(cond: "reputation", delta: 11), FDEffect(cond: "confiance", delta: 6)],
            ownLabel: "Contrôler et attendre du soutien",
            ownHint: "Tu as contrôlé en attendant du soutien. Le gardien est rentré dans sa cage, et l'occasion a disparu.",
            ownEffects: [FDEffect(attr: .control, delta: 5), FDEffect(rel: "vestiaire", delta: 4), FDEffect(cond: "reputation", delta: -4)]),
        FDLegendStep(
            age: 28, place: "Terrain, demi-finale internationale",
            text: "Le sommet de sa carrière : six buts en Coupe du monde et une demi-finale historique pour un pays de quatre millions d'habitants. Il a joué le dernier match avec une côte fêlée sans le dire à personne. Tu as la même côte fêlée et la même demi-finale devant toi.",
            followLabel: "Jouer la demi-finale en le cachant",
            followHint: "Tu as caché la côte fêlée et tu as joué la demi-finale. Ton pays a vécu la plus grande soirée de son histoire, et tu as fini plié en deux.",
            followEffects: [FDEffect(attr: .determination, delta: 6), FDEffect(cond: "reputation", delta: 11), FDEffect(rel: "fans", delta: 10), FDEffect(cond: "forme", delta: -12)],
            ownLabel: "Prévenir le staff",
            ownHint: "Tu as prévenu le staff. Tu es entré une demi-heure, protégé, et la demi-finale s'est jouée sans toi au début.",
            ownEffects: [FDEffect(rel: "staff", delta: 6), FDEffect(cond: "forme", delta: 6), FDEffect(cond: "reputation", delta: -6)]),
        FDLegendStep(
            age: 32, place: "Salle de conférence",
            text: "À trente-deux ans, il est devenu le visage de la reconstruction du football de son pays, en acceptant un rôle bénévole à la fédération pendant qu'il jouait encore. Ça lui a pris trois jours par semaine pendant deux ans. On te propose exactement ce rôle.",
            followLabel: "Prendre le rôle bénévole",
            followHint: "Tu as pris le rôle bénévole, trois jours par semaine, en plus de jouer. Le football de ton pays s'est reconstruit, et tu n'as pas dormi pendant deux ans.",
            followEffects: [FDEffect(attr: .leadership, delta: 6), FDEffect(rel: "fans", delta: 8), FDEffect(cond: "fatigue", delta: 12), FDEffect(cond: "forme", delta: -5)],
            ownLabel: "Rester concentré sur ta fin de carrière",
            ownHint: "Tu es resté concentré sur ton football. Tu as bien fini, et la fédération a bricolé sans toi.",
            ownEffects: [FDEffect(cond: "forme", delta: 6), FDEffect(cond: "moral", delta: 4), FDEffect(rel: "fans", delta: -4)]),
    ],
    "legend_libero_total": [
        FDLegendStep(
            age: 19, place: "Terrain d'entraînement",
            text: "Neesken pouvait jouer défenseur, milieu et attaquant dans la même action, parce qu'il a passé sa jeunesse à s'entraîner à tous les postes, en refusant d'en choisir un. Son coach de l'époque a mis deux ans à l'accepter. Ton coach te demande de choisir un poste, définitivement, ce matin.",
            followLabel: "Refuser de choisir un poste",
            followHint: "Tu as refusé de choisir un poste. Tu joues partout, tu comprends tout, et personne ne sait où t'écrire sur la feuille de match.",
            followEffects: [FDEffect(attr: .endurance, delta: 5), FDEffect(attr: .vision, delta: 5), FDEffect(attr: .placement, delta: 4), FDEffect(rel: "coach", delta: -5)],
            ownLabel: "Choisir un poste et t'y tenir",
            ownHint: "Tu as choisi un poste et tu t'y es tenu. Tu es devenu très bon à un endroit précis, et tu n'as plus jamais joué ailleurs.",
            ownEffects: [FDEffect(attr: .tacle, delta: 5), FDEffect(attr: .placement, delta: 4), FDEffect(rel: "coach", delta: 6), FDEffect(attr: .vision, delta: -2)]),
        FDLegendStep(
            age: 21, place: "Bureau du club",
            text: "À vingt et un ans, Neesken a refusé un transfert vers un club plus riche parce que son entraîneur du moment était le seul à comprendre sa manière de jouer partout. Il a suivi cet entraîneur pendant dix ans, de club en club. Ton coach part cet été, et un grand club te veut.",
            followLabel: "Suivre ton entraîneur, pas l'argent",
            followHint: "Tu as suivi ton entraîneur plutôt que l'argent. Personne d'autre n'a jamais su quoi faire de toi, et lui, oui.",
            followEffects: [FDEffect(rel: "coach", delta: 9), FDEffect(attr: .vision, delta: 5), FDEffect(money: -140000), FDEffect(cond: "reputation", delta: -3)],
            ownLabel: "Signer dans le grand club",
            ownHint: "Tu as signé dans le grand club. Le nouveau coach t'a mis à un poste fixe, et tu n'en es plus jamais sorti.",
            ownEffects: [FDEffect(money: 180000), FDEffect(cond: "reputation", delta: 7), FDEffect(attr: .vision, delta: -3)],
            followMove: "modeste",
            ownMove: "grand"),
        FDLegendStep(
            age: 23, place: "Vestiaire",
            text: "À vingt-trois ans, il a été le premier à réclamer publiquement une prime d'équipe identique pour tous les joueurs, titulaires ou pas. Le vestiaire l'a suivi, la direction l'a détesté. Ton vestiaire vote exactement ce sujet ce matin, et on te demande de parler en premier.",
            followLabel: "Défendre la prime égale pour tous",
            followHint: "Tu as défendu la prime égale pour tous. Le vestiaire t'a suivi, la direction ne l'a jamais digéré, et les remplaçants ne l'ont jamais oublié.",
            followEffects: [FDEffect(rel: "vestiaire", delta: 9), FDEffect(rel: "president", delta: -7), FDEffect(attr: .leadership, delta: 5), FDEffect(money: -30000)],
            ownLabel: "Laisser le système en place",
            ownHint: "Tu as laissé le système en place. Tu touches plus que les autres, et le vestiaire s'est divisé sans toi.",
            ownEffects: [FDEffect(money: 50000), FDEffect(rel: "vestiaire", delta: -5), FDEffect(rel: "president", delta: 5)]),
        FDLegendStep(
            age: 27, place: "Terrain, finale internationale",
            text: "Sa finale de Coupe du monde reste célèbre pour une chose : il a marqué le penalty le plus rapide de l'histoire d'une finale, à la deuxième minute, et son équipe a quand même perdu. Il a dit qu'il referait exactement pareil. Vous obtenez un penalty à la 2e minute d'une finale.",
            followLabel: "Le prendre et frapper tout de suite",
            followHint: "Tu as pris le penalty à la 2e minute d'une finale. Tu l'as mis, et le match a duré quatre-vingt-huit minutes de plus.",
            followEffects: [FDEffect(attr: .sangfroid, delta: 5), FDEffect(attr: .tir, delta: 4), FDEffect(cond: "reputation", delta: 9), FDEffect(cond: "fatigue", delta: 6)],
            ownLabel: "Laisser le tireur habituel",
            ownHint: "Tu as laissé le tireur désigné. Il l'a mis aussi, et personne ne parle jamais de qui n'a pas pris le ballon.",
            ownEffects: [FDEffect(rel: "vestiaire", delta: 5), FDEffect(attr: .sangfroid, delta: 3), FDEffect(cond: "reputation", delta: -4)]),
        FDLegendStep(
            age: 29, place: "Terrain, finale internationale",
            text: "Ce qu'on retient de lui : à vingt-neuf ans, en finale de Coupe du monde, il a joué à quatre postes différents en quatre-vingt-dix minutes, sur consigne du coach, sans jamais se plaindre. Ils ont perdu. Ton coach te demande de changer de poste pour la troisième fois du match.",
            followLabel: "Changer de poste autant qu'il le faut",
            followHint: "Tu as changé de poste quatre fois en quatre-vingt-dix minutes, sans broncher. La finale est perdue, et le coach n'a jamais eu de joueur pareil.",
            followEffects: [FDEffect(attr: .placement, delta: 5), FDEffect(attr: .endurance, delta: 5), FDEffect(rel: "coach", delta: 8), FDEffect(cond: "fatigue", delta: 10)],
            ownLabel: "Refuser le troisième changement",
            ownHint: "Tu as refusé le troisième changement. Tu es resté où tu étais bon, et le coach t'a sorti à la 75e.",
            ownEffects: [FDEffect(cond: "confiance", delta: 5), FDEffect(rel: "coach", delta: -6), FDEffect(attr: .placement, delta: 3)]),
        FDLegendStep(
            age: 32, place: "Bureau du club",
            text: "À trente-deux ans, il a demandé à jouer une saison entière à un poste qu'il n'avait jamais tenu, uniquement pour voir s'il en était capable. Le club a refusé et il l'a fait quand même en amical. Tu as exactement cette envie, et le coach a exactement la même réponse.",
            followLabel: "Aller au bout de l'idée",
            followHint: "Tu as joué à un poste inconnu, contre l'avis de tout le monde. C'était bancal, c'était passionnant, et tu as appris plus qu'en cinq ans.",
            followEffects: [FDEffect(attr: .vision, delta: 5), FDEffect(attr: .placement, delta: 4), FDEffect(rel: "coach", delta: -5), FDEffect(cond: "moral", delta: 6)],
            ownLabel: "Rester à ta place jusqu'au bout",
            ownHint: "Tu es resté à ta place jusqu'au bout. C'était le choix professionnel, et l'idée te trotte encore dans la tête.",
            ownEffects: [FDEffect(rel: "coach", delta: 5), FDEffect(cond: "forme", delta: 4), FDEffect(cond: "moral", delta: -3)]),
    ],
    "legend_eternel": [
        FDLegendStep(
            age: 17, place: "Vestiaire",
            text: "Buffoni est devenu titulaire à dix-sept ans dans un club qui jouait le maintien, et il a encaissé quatre buts pour son premier match. Il a rejoué le suivant. Vingt-deux saisons plus tard, il était encore là. Tu viens d'encaisser quatre buts pour ta première, et le coach doit décider ce soir.",
            followLabel: "Demander à rejouer tout de suite",
            followHint: "Tu as demandé à rejouer le match suivant, après en avoir pris quatre. Le coach a accepté, et tu n'as plus jamais rendu la place.",
            followEffects: [FDEffect(attr: .sangfroid, delta: 6), FDEffect(attr: .determination, delta: 5), FDEffect(cond: "confiance", delta: -4), FDEffect(cond: "fatigue", delta: 6)],
            ownLabel: "Laisser passer un match pour digérer",
            ownHint: "Tu as laissé passer un match. C'était sage, et le remplaçant a fait deux clean sheets.",
            ownEffects: [FDEffect(cond: "moral", delta: 5), FDEffect(rel: "staff", delta: 4), FDEffect(cond: "confiance", delta: -3)]),
        FDLegendStep(
            age: 20, place: "Bureau du club",
            text: "À vingt ans, Buffoni est devenu le gardien le plus cher de l'histoire, et il a passé les six mois suivants à entendre qu'il ne les valait pas. Il n'a jamais répondu une seule fois. Tu viens d'être transféré pour un montant record à ton poste, et la presse a commencé.",
            followLabel: "Ne jamais répondre aux critiques",
            followHint: "Tu n'as jamais répondu aux critiques sur ton prix. Six mois difficiles, et vingt ans pour prouver le contraire.",
            followEffects: [FDEffect(attr: .sangfroid, delta: 6), FDEffect(attr: .determination, delta: 5), FDEffect(cond: "moral", delta: -4), FDEffect(rel: "media", delta: 5)],
            ownLabel: "Répondre une bonne fois",
            ownHint: "Tu as répondu une bonne fois. Ça a soulagé, et ça a donné trois jours de titres supplémentaires.",
            ownEffects: [FDEffect(cond: "confiance", delta: 5), FDEffect(rel: "media", delta: -5), FDEffect(cond: "moral", delta: 4)]),
        FDLegendStep(
            age: 22, place: "Bureau du président",
            text: "À vingt-deux ans, son club a été rétrogradé administrativement en deuxième division. Il était le meilleur gardien du pays et il pouvait partir gratuitement. Il est resté, et c'est ce choix-là qui a fait sa légende avant tous ses trophées. Ton club vient de subir exactement ça.",
            followLabel: "Rester en deuxième division",
            followHint: "Tu es resté en deuxième division alors que tu pouvais partir libre. Le club est remonté, et une ville entière te doit quelque chose pour toujours.",
            followEffects: [FDEffect(rel: "fans", delta: 10), FDEffect(rel: "president", delta: 9), FDEffect(cond: "reputation", delta: -6), FDEffect(money: -120000)],
            ownLabel: "Partir, tu es au sommet",
            ownHint: "Tu es parti, librement, au sommet. C'était ton droit le plus strict, et la ville a mis dix ans à en reparler autrement.",
            ownEffects: [FDEffect(cond: "reputation", delta: 7), FDEffect(money: 180000), FDEffect(rel: "fans", delta: -9)],
            ownMove: "grand"),
        FDLegendStep(
            age: 25, place: "Ligne de but, finale continentale",
            text: "Sa parade la plus célèbre : à vingt-cinq ans, en finale européenne, une double parade dont la deuxième sur sa ligne, à genoux, sur une reprise à trois mètres. Il a dit qu'il n'avait pas bougé, que le ballon était venu à lui. Tu es à genoux, le ballon revient sur le buteur.",
            followLabel: "Rester grand et attendre",
            followHint: "Tu es resté grand et tu as attendu. Le ballon est venu dans tes mains, et la finale est restée à 0-0.",
            followEffects: [FDEffect(attr: .placement, delta: 6), FDEffect(attr: .sangfroid, delta: 6), FDEffect(cond: "reputation", delta: 10), FDEffect(cond: "fatigue", delta: 6)],
            ownLabel: "Plonger dans les pieds",
            ownHint: "Tu as plongé dans les pieds. Il t'a lobé, ou il a raté — c'est le genre de seconde où l'on ne réfléchit pas.",
            ownEffects: [FDEffect(attr: .agilite, delta: 5), FDEffect(cond: "confiance", delta: 4), FDEffect(cond: "reputation", delta: -3)]),
        FDLegendStep(
            age: 28, place: "Vestiaire, finale internationale",
            text: "Sa finale de Coupe du monde s'est jouée aux tirs au but, et il a passé la séance à parler à chaque tireur adverse avant sa course d'élan. Deux ont craqué. On a beaucoup discuté de la limite. Tu es dans cette séance de tirs au but, ce soir, avec la même possibilité.",
            followLabel: "Parler à chaque tireur, comme lui",
            followHint: "Tu as parlé à chaque tireur avant sa course. Deux ont craqué, le trophée est à vous, et la moitié du monde a trouvé ça déloyal.",
            followEffects: [FDEffect(attr: .sangfroid, delta: 6), FDEffect(cond: "reputation", delta: 9), FDEffect(rel: "media", delta: -5), FDEffect(cond: "fatigue", delta: 7)],
            ownLabel: "Rester silencieux sur ta ligne",
            ownHint: "Tu es resté silencieux sur ta ligne. Tu en as arrêté un, proprement, sans avoir eu besoin de parler.",
            ownEffects: [FDEffect(attr: .agilite, delta: 5), FDEffect(attr: .sangfroid, delta: 4), FDEffect(cond: "reputation", delta: 5)]),
        FDLegendStep(
            age: 34, place: "Bureau du club",
            text: "À trente-quatre ans, il a accepté d'être numéro deux derrière un gardien de vingt-trois ans, sans jamais se plaindre, pour finir dans son club. Il a fait deux saisons de banc irréprochables. On te propose exactement ce rôle, et tu peux encore être titulaire ailleurs.",
            followLabel: "Accepter d'être numéro deux",
            followHint: "Tu as accepté le banc pour finir dans ton club. Deux saisons irréprochables, et un jeune gardien qui te doit sa carrière.",
            followEffects: [FDEffect(rel: "vestiaire", delta: 8), FDEffect(rel: "coach", delta: 6), FDEffect(cond: "moral", delta: -5), FDEffect(cond: "reputation", delta: -4)],
            ownLabel: "Partir être titulaire ailleurs",
            ownHint: "Tu es parti être titulaire ailleurs. Tu as joué chaque semaine, loin de ceux qui t'ont vu grandir.",
            ownEffects: [FDEffect(cond: "confiance", delta: 6), FDEffect(cond: "forme", delta: 5), FDEffect(rel: "fans", delta: -6)],
            ownMove: "modeste"),
    ],
    "legend_rei_do_gol": [
        FDLegendStep(
            age: 18, place: "Terrain, club formateur",
            text: "Garrinche a signé à dix-huit ans dans le club de sa ville pour l'équivalent de rien, en refusant les grands clubs de la capitale, parce qu'il ne voulait pas quitter sa rue. Il y est resté toute sa carrière et il y a tout gagné. On te propose exactement ce choix ce matin.",
            followLabel: "Rester dans le club de ta ville",
            followHint: "Tu es resté dans le club de ta rue, pour presque rien. Tu y as tout gagné, et tu n'as jamais habité ailleurs.",
            followEffects: [FDEffect(rel: "fans", delta: 10), FDEffect(cond: "moral", delta: 7), FDEffect(money: -70000), FDEffect(cond: "reputation", delta: -4)],
            ownLabel: "Signer dans un grand club de la capitale",
            ownHint: "Tu as signé dans la capitale. Le niveau est plus haut, la ville plus grande, et ta rue a suivi ça à la radio.",
            ownEffects: [FDEffect(cond: "reputation", delta: 7), FDEffect(money: 90000), FDEffect(rel: "fans", delta: -6)],
            ownMove: "grand"),
        FDLegendStep(
            age: 22, place: "Terrain d'entraînement",
            text: "Sa manière de dribbler était unique et son coach a voulu la rationaliser pour la rendre plus efficace. Il a refusé net, en disant qu'il jouait comme il respirait. Le coach a cédé. Le tien vient de te demander exactement de rationaliser ce que tu fais d'instinct.",
            followLabel: "Refuser de rationaliser ton jeu",
            followHint: "Tu as refusé de rationaliser ton jeu. Tu joues comme tu respires, et le staff a arrêté d'essayer de te corriger.",
            followEffects: [FDEffect(attr: .dribble, delta: 6), FDEffect(cond: "confiance", delta: 6), FDEffect(rel: "coach", delta: -5), FDEffect(attr: .placement, delta: -2)],
            ownLabel: "Accepter de discipliner ton jeu",
            ownHint: "Tu as accepté de discipliner ton jeu. Tu es plus efficace, plus lisible, et un peu moins toi.",
            ownEffects: [FDEffect(attr: .placement, delta: 5), FDEffect(attr: .passe, delta: 4), FDEffect(rel: "coach", delta: 6), FDEffect(attr: .dribble, delta: -3)]),
        FDLegendStep(
            age: 24, place: "Bureau du club",
            text: "À vingt-quatre ans, Garrinche a refusé le transfert le plus riche jamais proposé dans son pays, offert par le club rival de sa ville. Il a dit qu'il ne pouvait pas traverser la rue. Le rival de ta ville vient de proposer exactement ce montant.",
            followLabel: "Refuser de traverser la rue",
            followHint: "Tu as refusé de traverser la rue, même pour ce montant. Ta ville te doit quelque chose pour toujours.",
            followEffects: [FDEffect(rel: "fans", delta: 11), FDEffect(cond: "moral", delta: 7), FDEffect(money: -260000)],
            ownLabel: "Accepter et traverser",
            ownHint: "Tu as traversé la rue. Le contrat est historique, et ton ancien quartier a effacé ton nom des murs.",
            ownEffects: [FDEffect(money: 340000), FDEffect(cond: "reputation", delta: 7), FDEffect(rel: "fans", delta: -12)],
            ownMove: "rival"),
        FDLegendStep(
            age: 26, place: "Terrain, finale internationale",
            text: "Sa Coupe du monde reste la référence absolue : il a joué la finale à vingt-six ans avec une cheville deux fois plus grosse que l'autre, et il a fait la différence sur une action que personne n'a jamais su expliquer. Ta cheville est dans cet état, et la finale est ce soir.",
            followLabel: "Jouer la finale sur une jambe",
            followHint: "Tu as joué la finale sur une jambe et demie, et tu as fait la différence. Personne n'a jamais compris comment.",
            followEffects: [FDEffect(attr: .dribble, delta: 6), FDEffect(cond: "reputation", delta: 12), FDEffect(cond: "forme", delta: -11), FDEffect(rel: "fans", delta: 10)],
            ownLabel: "Écouter ton corps",
            ownHint: "Tu as écouté ton corps et tu es resté sur le banc. Ton équipe a gagné sans toi, et tu marchais normalement le lendemain.",
            ownEffects: [FDEffect(cond: "forme", delta: 8), FDEffect(rel: "staff", delta: 5), FDEffect(cond: "reputation", delta: -7)]),
        FDLegendStep(
            age: 29, place: "Surface adverse, match de championnat",
            text: "Son millième but : à vingt-neuf ans, un penalty qu'il a demandé à tirer alors qu'il n'était pas le tireur, dans un stade plein venu pour ça. Il a mis vingt minutes à rejoindre les vestiaires ensuite. Tu es à un but d'un chiffre rond, et le penalty n'est pas pour toi.",
            followLabel: "Réclamer le penalty pour le chiffre",
            followHint: "Tu as réclamé le penalty pour le chiffre rond. Tu l'as mis, le stade a envahi la pelouse, et le tireur désigné a regardé.",
            followEffects: [FDEffect(attr: .tir, delta: 5), FDEffect(cond: "reputation", delta: 10), FDEffect(rel: "fans", delta: 9), FDEffect(rel: "vestiaire", delta: -4)],
            ownLabel: "Laisser le tireur désigné",
            ownHint: "Tu as laissé le tireur désigné. Il l'a mis, le stade a applaudi poliment, et ton chiffre a attendu trois semaines.",
            ownEffects: [FDEffect(rel: "vestiaire", delta: 6), FDEffect(cond: "reputation", delta: -3)]),
        FDLegendStep(
            age: 31, place: "Salon familial",
            text: "À trente et un ans, il a refusé le plus gros contrat jamais proposé à un joueur de son pays pour ne pas partir à l'étranger, contre l'avis de toute sa famille. Il a dit qu'il n'aurait pas su qui il était là-bas. La même offre est arrivée, et le salon est plein.",
            followLabel: "Refuser de partir, comme lui",
            followHint: "Tu as refusé de partir. Tu es resté celui que tu es, et ta famille a mis des années à ne plus en parler.",
            followEffects: [FDEffect(cond: "moral", delta: 7), FDEffect(rel: "fans", delta: 9), FDEffect(money: -350000), FDEffect(rel: "famille", delta: -6)],
            ownLabel: "Prendre le contrat et partir",
            ownHint: "Tu as pris le contrat historique. Ta famille est à l'abri définitivement, et tu as passé quatre ans à te demander qui tu étais là-bas.",
            ownEffects: [FDEffect(money: 500000), FDEffect(cond: "reputation", delta: 6), FDEffect(cond: "moral", delta: -5)],
            ownMove: "etranger"),
    ],
    "legend_ombre_dor": [
        FDLegendStep(
            age: 19, place: "Terrain d'entraînement",
            text: "Figoa a construit sa carrière sur une obsession : redéfinir le métier d'attaquant en travaillant les courses sans ballon, celles que personne ne remarque. À dix-neuf ans, il a demandé à travailler ça deux heures par jour, seul. Ton adjoint te propose ces deux heures ingrates.",
            followLabel: "Travailler les courses sans ballon",
            followHint: "Tu as passé deux heures par jour sur des courses que personne ne remarque. Aujourd'hui, tu es toujours démarqué et personne ne sait pourquoi.",
            followEffects: [FDEffect(attr: .placement, delta: 6), FDEffect(attr: .endurance, delta: 4), FDEffect(cond: "fatigue", delta: 8), FDEffect(cond: "moral", delta: -3)],
            ownLabel: "Travailler avec le ballon",
            ownHint: "Tu as travaillé avec le ballon, comme tout le monde. Tes gestes sont propres, et tu reçois toujours dos au but.",
