            followLabel: "Accepter d'être troisième choix ailleurs",
            followHint: "Tu as accepté d'être troisième choix dans un championnat plus dur. Dix-huit mois de patience, et une place que tu n'as plus jamais lâchée.",
            followEffects: [FDEffect(attr: .control, delta: 5), FDEffect(attr: .determination, delta: 5), FDEffect(cond: "confiance", delta: -4), FDEffect(cond: "reputation", delta: 6)],
