            ownLabel: "Refuser par respect pour ton club",
            ownHint: "Tu as refusé le rival. Ton virage t'a porté aux nues pendant deux ans, et tu as laissé passer le plus gros contrat de ta vie.",
            ownEffects: [FDEffect(rel: "fans", delta: 10), FDEffect(cond: "moral", delta: 6), FDEffect(money: -100000)],
            followMove: "rival"),
        FDLegendStep(
            age: 27, place: "Terrain, finale continentale",
            text: "Sa finale européenne s'est jouée sur une passe décisive donnée à la 118e minute, alors qu'il aurait pu frapper lui-même et devenir le héros. Il a dit après qu'il avait vu le meilleur choix et rien d'autre. Tu es exactement dans cette situation, à cette minute-là.",
            followLabel: "Donner la passe, comme lui",
            followHint: "Tu as donné la passe à la 118e alors que tu pouvais frapper. Le trophée est là, et un autre nom est dans les résumés.",
            followEffects: [FDEffect(attr: .vision, delta: 6), FDEffect(attr: .passe, delta: 5), FDEffect(rel: "vestiaire", delta: 8), FDEffect(cond: "reputation", delta: -3)],
            ownLabel: "Frapper et devenir le héros",
            ownHint: "Tu as frappé. Héros ou coupable, tu as pris ce ballon pour toi et tout le monde le sait.",
            ownEffects: [FDEffect(attr: .tir, delta: 5), FDEffect(cond: "reputation", delta: 9), FDEffect(rel: "vestiaire", delta: -4), FDEffect(cond: "confiance", delta: 6)]),
        FDLegendStep(
            age: 29, place: "Terrain, derby",
            text: "L'épisode le plus violent de sa carrière : à vingt-neuf ans, revenu dans son ancien stade avec le maillot du rival, on lui a jeté des objets pendant tout le match, et il a demandé à tirer chaque corner du côté du virage. Tu reviens dans ce stade ce soir, avec l'autre maillot.",
            followLabel: "Aller tirer les corners devant le virage",
            followHint: "Tu es allé tirer chaque corner devant le virage qui te haïssait. Ils t'ont tout jeté dessus, et tu n'as pas reculé d'un mètre.",
            followEffects: [FDEffect(cond: "confiance", delta: 8), FDEffect(cond: "reputation", delta: 8), FDEffect(rel: "fans", delta: -6), FDEffect(cond: "fatigue", delta: 6)],
